function* fibonacci(): Generator<bigint> {      // lazy, single-use, typed
  let [a, b] = [0n, 1n];
  while (true) { yield a; [a, b] = [b, a + b]; }
}

const first: bigint[] = [];
for (const n of fibonacci()) {                  // IterableIterator<bigint>
  if (n > 100n) break;
  first.push(n);
}

